// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }
    function testFuzz_property(uint256 fuzz_seed) public {
        vm.assume(fuzz_seed > 0);
        address player = address(uint160(uint256(keccak256(abi.encode(fuzz_seed)))));
        uint256 ticket = 10;
        vm.deal(player, ticket);
        vm.prank(player);
        c.play{value: ticket}();
        uint256 potAfter = c.pot();
        bool potIsZero = (potAfter == 0);
        bool potEqualsTicket = (potAfter == ticket);
        assertTrue(potIsZero || potEqualsTicket);
    }
}
